package com.interview;
import java.util.*;
public final class Json {
 public static String write(Object o){if(o==null)return "null";if(o instanceof String s)return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t").replaceAll("[\\x00-\\x1f]", " ")+"\"";if(o instanceof Number||o instanceof Boolean)return o.toString();if(o instanceof Map<?,?> m){List<String>a=new ArrayList<>();m.forEach((k,v)->a.add(write(k.toString())+":"+write(v)));return "{"+String.join(",",a)+"}";}if(o instanceof Collection<?> c)return "["+String.join(",",c.stream().map(Json::write).toList())+"]";throw new IllegalArgumentException("Unsupported JSON value");}
 public static Object read(String s){Parser p=new Parser(s);Object o=p.value(0);p.ws();if(p.i!=s.length())throw new IllegalArgumentException("Invalid JSON");return o;}
 @SuppressWarnings("unchecked") public static Map<String,Object> obj(Object o){if(!(o instanceof Map))throw new IllegalArgumentException("Expected object");return (Map<String,Object>)o;}
 static class Parser {String s;int i;Parser(String s){this.s=s;}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}char take(){if(i>=s.length())throw new IllegalArgumentException("Invalid JSON");return s.charAt(i++);}Object value(int depth){if(depth>30)throw new IllegalArgumentException("JSON too deep");ws();if(i>=s.length())throw new IllegalArgumentException("Invalid JSON");char c=s.charAt(i);if(c=='"')return str();if(c=='{'||c=='['){i++;boolean map=c=='{';Map<String,Object>m=new LinkedHashMap<>();List<Object>a=new ArrayList<>();ws();if(i<s.length()&&s.charAt(i)==(map?'}':']')){i++;return map?m:a;}while(true){ws();String k=null;if(map){k=str();ws();if(take()!=':')throw new IllegalArgumentException("Invalid JSON");}Object v=value(depth+1);if(map)m.put(k,v);else a.add(v);ws();char end=take();if(end==(map?'}':']'))return map?m:a;if(end!=',')throw new IllegalArgumentException("Invalid JSON");}}for(String lit:List.of("true","false","null"))if(s.startsWith(lit,i)){i+=lit.length();return lit.equals("null")?null:lit.equals("true");}int start=i;while(i<s.length()&&"-+0123456789.eE".indexOf(s.charAt(i))>=0)i++;if(start==i)throw new IllegalArgumentException("Invalid JSON");try{return Double.valueOf(s.substring(start,i));}catch(Exception e){throw new IllegalArgumentException("Invalid number");}}String str(){if(take()!='"')throw new IllegalArgumentException("Expected string");StringBuilder b=new StringBuilder();while(true){char c=take();if(c=='"')return b.toString();if(c<32)throw new IllegalArgumentException("Invalid string");if(c=='\\'){c=take();switch(c){case '"','\\','/'->b.append(c);case 'n'->b.append('\n');case 'r'->b.append('\r');case 't'->b.append('\t');case 'b'->b.append('\b');case 'f'->b.append('\f');case 'u'->{if(i+4>s.length())throw new IllegalArgumentException("Invalid unicode");b.append((char)Integer.parseInt(s.substring(i,i+4),16));i+=4;}default->throw new IllegalArgumentException("Invalid escape");}}else b.append(c);}}}
}
